spec.expr:
(
  sum(
    rate(pizza_purchase_duration_ms_milliseconds_sum{
      service_name="jwt-pizza-service"
    }[5m])
  )
  /
  sum(
    rate(pizza_purchase_duration_ms_milliseconds_count{
      service_name="jwt-pizza-service"
    }[5m])
  )
) or vector(0)

count(
  sum by (user_id) (
    increase(active_user_requests_total{
      service_name="jwt-pizza-service"
    }[5m])
  ) > 0
) or vector(0)

(
  sum(
    rate(http_request_duration_ms_milliseconds_sum{
      service_name="jwt-pizza-service"
    }[5m])
  )
  /
  sum(
    rate(http_request_duration_ms_milliseconds_count{
      service_name="jwt-pizza-service"
    }[5m])
  )
) or vector(0)

sum(
  rate(pizza_purchases_total{
    service_name="jwt-pizza-service",
    status="failure"
  }[5m]) * 60
) or vector(0)
